import { render } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { EntityCard } from "../EntityCard/index.js";
import TokenSwatch from "./TokenSwatch.js";

/** The value a half's well paints, read from its inline channel. */
const readWell = (half: Element | null): string | undefined => {
  const well = half?.querySelector(".value");
  return well instanceof HTMLElement
    ? well.style.getPropertyValue("--token-swatch-value")
    : undefined;
};

describe("TokenSwatch", () => {
  it("paints the light value, then the dark one, each named under its well", () => {
    const { container } = render(
      <TokenSwatch dark="#262626" light="#ffffff" />,
    );
    const swatch = container.firstElementChild;
    expect(swatch?.className).toBe("ds token-swatch");
    const halves = [...(swatch?.children ?? [])];
    expect(halves.map(({ className }) => className)).toEqual([
      "in-light",
      "in-dark",
    ]);
    expect(readWell(halves.at(0) ?? null)).toBe("#ffffff");
    expect(readWell(halves.at(1) ?? null)).toBe("#262626");
    expect(
      halves.map((half) =>
        [...half.children].map(({ className }) => className),
      ),
    ).toEqual([
      ["value", "mode"],
      ["value", "mode"],
    ]);
    expect(
      halves.map((half) => half.querySelector(".mode")?.textContent),
    ).toEqual(["Light", "Dark"]);
  });

  it("hides the mode names, so the specimen's label alone names it", () => {
    const { getByRole } = render(
      <EntityCard.Specimen
        kind="swatch"
        label="color.background: #ffffff in light, #262626 in dark"
      >
        <TokenSwatch dark="#262626" light="#ffffff" />
      </EntityCard.Specimen>,
    );
    const specimen = getByRole("img", {
      name: "color.background: #ffffff in light, #262626 in dark",
    });
    expect(specimen.getAttribute("data-specimen")).toBe("swatch");
    for (const mode of specimen.querySelectorAll(".mode")) {
      expect(mode.getAttribute("aria-hidden")).toBe("true");
    }
  });

  it("keeps the caller's class and props beside its own", () => {
    const { container } = render(
      <TokenSwatch
        className="wide"
        dark="#262626"
        data-testid="swatch"
        light="#ffffff"
      />,
    );
    const swatch = container.firstElementChild;
    expect(swatch?.className).toBe("ds token-swatch wide");
    expect(swatch?.getAttribute("data-testid")).toBe("swatch");
  });
});
